import{_ as e,c as a,o as r,ag as d}from"./chunks/framework.C7v41-tM.js";const m=JSON.parse('{"title":"查找本机 MCP：发现配置，不等于服务可用","description":"","frontmatter":{},"headers":[],"relativePath":"notes/mcp-discovery.md","filePath":"notes/mcp-discovery.md"}'),o={name:"notes/mcp-discovery.md"};function n(c,t,i,h,l,s){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="查找本机-mcp-发现配置-不等于服务可用" tabindex="-1">查找本机 MCP：发现配置，不等于服务可用 <a class="header-anchor" href="#查找本机-mcp-发现配置-不等于服务可用" aria-label="Permalink to &quot;查找本机 MCP：发现配置，不等于服务可用&quot;">​</a></h1><p>盘点的第一步是收集证据，不是启动所有发现的程序。协议解释见 <a href="https://github.com/lixudong1649/jdp-wiki/blob/main/content/terms/mcp.md" target="_blank" rel="noreferrer">MCP</a>。</p><h2 id="分开记录四层状态" tabindex="-1">分开记录四层状态 <a class="header-anchor" href="#分开记录四层状态" aria-label="Permalink to &quot;分开记录四层状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>典型证据</th><th>不能直接推出什么</th></tr></thead><tbody><tr><td>配置存在</td><td>客户端保存服务定义</td><td>服务已安装或正在运行</td></tr><tr><td>安装／缓存存在</td><td>包目录或插件登记</td><td>当前启用、版本适用</td></tr><tr><td>当前会话可发现</td><td>宿主列出能力</td><td>业务调用一定成功</td></tr><tr><td>代表调用成功</td><td>实际只读调用及结果</td><td>对所有用户和时点都可用</td></tr></tbody></table><p>教学例子：同名服务出现在两个客户端，可能有不同端点、版本和权限。按名称合并会丢证据；应保留来源、作用域、配置和观察时间。</p><h2 id="安全的盘点流程" tabindex="-1">安全的盘点流程 <a class="header-anchor" href="#安全的盘点流程" aria-label="Permalink to &quot;安全的盘点流程&quot;">​</a></h2><p>从已授权的客户端与项目范围读取配置，只输出需要的服务名、传输提示、版本和开关。敏感字段只显示“已配置／缺失”或受控引用，不打印完整环境变量和请求头。</p><p>静态诊断检查格式、路径和变量是否具备。连接测试单独授权；不要为查询版本执行配置中的任意 command。代表测试优先使用已知答案的只读工具。</p><h2 id="结果怎么写" tabindex="-1">结果怎么写 <a class="header-anchor" href="#结果怎么写" aria-label="Permalink to &quot;结果怎么写&quot;">​</a></h2><p>分别标注未扫描、未知、未连接、失败和已验证。发现模块不自动导入别的客户端凭据，也不将磁盘缓存计入当前会话可用服务数量。</p><p>参考：<a href="https://modelcontextprotocol.io/docs/learn/architecture" target="_blank" rel="noreferrer">MCP 架构</a>。状态分层为盘点方法建议，整理：2026-10-14。本文不包含真实设备路径、配置或凭据。</p>',11)])])}const _=e(o,[["render",n]]);export{m as __pageData,_ as default};
